// HasSet applies the HasEdge predicate on the "set" edge.
func HasSet() predicate.CommitRow {
	return predicate.CommitRow(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, SetTable, SetColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasSetWith applies the HasEdge predicate on the "set" edge with a given conditions (other predicates).
func HasSetWith(preds ...predicate.Set) predicate.CommitRow {
	return predicate.CommitRow(func(s *sql.Selector) {
		step := newSetStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CommitRow) predicate.CommitRow {
	return predicate.CommitRow(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CommitRow) predicate.CommitRow {
	return predicate.CommitRow(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CommitRow) predicate.CommitRow {
	return predicate.CommitRow(sql.NotPredicates(p))
}
